61	export function $caretFromPoint<D extends CaretDirection>(
62	  point: Pick<PointType, 'type' | 'key' | 'offset'>,
63	  direction: D,
64	): PointCaret<D> {
65	  const {type, key, offset} = point;
66	  const node = $getNodeByKeyOrThrow(point.key);
67	  if (type === 'text') {
68	    invariant(
69	      $isTextNode(node),
70	      '$caretFromPoint: Node with type %s and key %s that does not inherit from TextNode encountered for text point',
71	      node.getType(),
72	      key,
73	    );
74	    return $getTextPointCaret(node, direction, offset);
75	  }
76	  invariant(
77	    $isElementNode(node),
78	    '$caretFromPoint: Node with type %s and key %s that does not inherit from ElementNode encountered for element point',
79	    node.getType(),
80	    key,
81	  );
82	  return $getChildCaretAtIndex(node, point.offset, direction);
83	}
