85	/**
86	 * Update the given point in-place from the PointCaret
87	 *
88	 * @param point the point to set
89	 * @param caret the caret to set the point from
90	 */
91	export function $setPointFromCaret<D extends CaretDirection>(
92	  point: PointType,
93	  caret: PointCaret<D>,
94	): void {
95	  const {origin, direction} = caret;
96	  const isNext = direction === 'next';
97	  if ($isTextPointCaret(caret)) {
98	    point.set(origin.getKey(), caret.offset, 'text');
99	  } else if ($isSiblingCaret(caret)) {
100	    if ($isTextNode(origin)) {
101	      point.set(origin.getKey(), $getTextNodeOffset(origin, direction), 'text');
102	    } else {
103	      point.set(
104	        origin.getParentOrThrow().getKey(),
105	        origin.getIndexWithinParent() + (isNext ? 1 : 0),
106	        'element',
107	      );
108	    }
109	  } else {
110	    invariant(
111	      $isChildCaret(caret) && $isElementNode(origin),
112	      '$setPointFromCaret: exhaustiveness check',
113	    );
114	    point.set(
115	      origin.getKey(),
116	      isNext ? 0 : origin.getChildrenSize(),
117	      'element',
118	    );
119	  }
120	}
