import {$createHeadingNode, $createQuoteNode} from '@lexical/rich-text';
import {$createListItemNode, $createListNode} from '@lexical/list';
import {
  $createParagraphNode,
  $createTextNode,
  $getRoot,
  $setSelection,
} from 'lexical';
import {describe, expect, test} from 'vitest';

import {initializeUnitTest} from '../utils';

describe('scratch backspace', () => {
  initializeUnitTest((testEnv) => {
    test('heading preceded by empty paragraph, extra blocks after', async () => {
      const {editor} = testEnv;
      await editor.update(() => {
        const root = $getRoot();
        root.clear();
        const empty = $createParagraphNode();
        const heading = $createHeadingNode('h1');
        heading.append($createTextNode('abc'));
        const after = $createParagraphNode();
        after.append($createTextNode('xyz'));
        root.append(empty, heading, after);
        heading.selectStart();
      });
      await editor.update(() => {
        const sel = $getRoot();
        const selection = require('lexical').$getSelection();
        selection.deleteCharacter(true);
      });
      editor.read(() => {
        const root = $getRoot();
        const kids = root.getChildren();
        expect(kids.map((k: any) => k.getType())).toEqual([
          'heading',
          'paragraph',
        ]);
        expect(kids[0].getTextContent()).toBe('abc');
        expect(kids[1].getTextContent()).toBe('xyz');
      });
    });

    test('quote preceded by empty paragraph', async () => {
      const {editor} = testEnv;
      await editor.update(() => {
        const root = $getRoot();
        root.clear();
        const empty = $createParagraphNode();
        const quote = $createQuoteNode();
        quote.append($createTextNode('hi'));
        root.append(empty, quote);
        quote.selectStart();
      });
      await editor.update(() => {
        require('lexical').$getSelection().deleteCharacter(true);
      });
      editor.read(() => {
        const kids = $getRoot().getChildren();
        expect(kids.map((k: any) => k.getType())).toEqual(['quote']);
        expect(kids[0].getTextContent()).toBe('hi');
      });
    });

    test('heading preceded by list (empty item) uses default merge', async () => {
      const {editor} = testEnv;
      await editor.update(() => {
        const root = $getRoot();
        root.clear();
        const list = $createListNode('bullet');
        list.append($createListItemNode());
        const heading = $createHeadingNode('h1');
        heading.append($createTextNode('abc'));
        root.append(list, heading);
        heading.selectStart();
      });
      await editor.update(() => {
        require('lexical').$getSelection().deleteCharacter(true);
      });
      editor.read(() => {
        const kids = $getRoot().getChildren();
        // default merge: heading text merged into the list, no standalone heading kept
        expect(kids.map((k: any) => k.getType())).toEqual(['list']);
      });
    });

    test('non-empty heading with no previous block is unchanged', async () => {
      const {editor} = testEnv;
      await editor.update(() => {
        const root = $getRoot();
        root.clear();
        const heading = $createHeadingNode('h2');
        heading.append($createTextNode('abc'));
        root.append(heading);
        heading.selectStart();
      });
      await editor.update(() => {
        require('lexical').$getSelection().deleteCharacter(true);
      });
      editor.read(() => {
        const kids = $getRoot().getChildren();
        expect(kids.map((k: any) => k.getType())).toEqual(['heading']);
        expect((kids[0] as any).getTag()).toBe('h2');
        expect(kids[0].getTextContent()).toBe('abc');
      });
    });
  });
});
